<span class="line"><span style="color:#E5C07B;">    context</span><span style="color:#ABB2BF;"> =&gt; </span><span style="color:#E5C07B;">context</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Request</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Path</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">StartsWithSegments</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;/api&quot;</span><span style="color:#ABB2BF;">),</span></span>
