<span class="line"><span style="color:#E5C07B;">builder</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Services</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">AddCors</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">options</span><span style="color:#ABB2BF;"> =&gt;</span></span>
